// matching [`moraine_inline_file_deletes`] call, not yet freed.
void moraine_inline_file_deletes_free(struct MoraineInlineFileDeleteRow *items, size_t len);

// Drains every buffered log record into `sink`, oldest first.
//
// Called by the shim on a thread that holds a DuckDB `ClientContext`, so
// the records can be written through DuckDB's own logger. Never fails and
// never allocates on the caller's behalf: each message is borrowed for the
// duration of its `sink` call and freed after it returns.
//
// # Safety
//
// `sink`, if non-null, must be callable with `sink_ctx` and must not
// unwind. It must not re-enter any `moraine_*` entry point.
void moraine_drain_logs(MoraineLogSink sink, void *sink_ctx);

// Registers `sink` as the delivery target for `handle`'s events, first
// handing it whatever the buffer already holds from that handle so
// nothing captured before registration is lost.
//
// While registered, the handle's events bypass the buffer and the
// boundary drains — records surface as they happen, which for a long
// commit is while the commit still runs. Other handles' events are
// untouched: each routes to its own sink or, without one, to the buffer.
// Registering again for the same handle replaces its sink.
//
// # Safety
//
// `handle` must be a live pointer from `moraine_attach`. `sink`, if
// non-null, must be callable with `ctx` from any thread until
// unregistration returns, must not unwind, must not emit `tracing`
// events, and must not re-enter any `moraine_*` entry point.
void moraine_register_log_sink(const struct MoraineCatalogHandle *handle,
                               MoraineLogSink sink,
                               void *ctx);

// Removes `handle`'s sink, if one is registered. When it returns, no call
// to that sink is in flight and none will follow — its `ctx` may be torn
// down. The handle's later events fall back to the buffer.
//
// # Safety
//
// `handle` must be a live pointer from `moraine_attach`. Must not be
// called from inside a sink.
void moraine_unregister_log_sink(const struct MoraineCatalogHandle *handle);

// Opens a staged-row transaction at the current head and writes the
// resulting handle to `*out`.
//
// Cancellable: races the head read against `probe` (polled
// immediately, then ~100 ms; a null `probe` disables polling). If a
// cancellation wins, returns [`codes::INTERRUPTED`], `*out` is left
// unwritten, and nothing is staged.
//
// # Safety
//
// `handle` must be a pointer previously returned by
// [`moraine_attach`](crate::abi::moraine_attach) and not yet detached,
// and must outlive every operation on the returned transaction handle
// (through [`moraine_tx_commit`] or [`moraine_tx_rollback`]). `out`
// must be a valid, writable `*mut *mut MoraineTxHandle`. `probe`, if
// non-null, must be safe to call with `probe_ctx` from any thread.
// `err`, if non-null, must be a valid, writable [`MoraineError`]. All
// for the duration of this call.
int32_t moraine_tx_begin(struct MoraineCatalogHandle *handle,
                         struct MoraineTxHandle **out,
                         MoraineInterruptProbe probe,
                         void *probe_ctx,
                         struct MoraineError *err);

// Accumulates one staged row mutation. Nothing touches the store until
// [`moraine_tx_commit`]. `table_kind` is [`TableKind`]'s discriminant
// order (`0` = `Snapshot`, `1` = `SnapshotChanges`, `2` = `Schema`, `3` =
// `Table`, `4` = `View`, `5` = `Column`, `6` = `DataFile`, `7` =
// `DeleteFile`, `8` = `TableStats`, `9` = `TableColumnStats`, `10` =
// `FileColumnStats`, `11` = `SchemaVersions`, `12` = `PartitionInfo`,
// `13` = `PartitionColumn`, `14` = `FilePartitionValue`, `15` =
// `SortInfo`, `16` = `SortExpression`, `17` = `Tag`, `18` =
// `ColumnTag`, `19` = `FilesScheduledForDeletion`); `operation_kind` is
// `0` = insert, `1` = delete, `2` = update-sets-`end_snapshot`, `3` =
// update-sets-`begin_snapshot`. `cells` are positional
// in the column order the shim declares for `table_kind`'s table (a delete
// or update-set-end row carries only the key columns, per [`RowOperation`]'s
// variants).
//
// # Safety
//
// `tx` must be a pointer previously returned by [`moraine_tx_begin`]
// and not yet committed or rolled back. `cells`, if `cells_len` is
// nonzero, must point to `cells_len` valid [`MoraineCell`]s (every
// non-null `str_value` inside a valid NUL-terminated UTF-8 C string).
// `err`, if non-null, must be a valid, writable [`MoraineError`]. All
// for the duration of this call.
int32_t moraine_tx_stage(struct MoraineTxHandle *tx,
                         int32_t table_kind,
                         int32_t operation_kind,
                         const struct MoraineCell *cells,
                         size_t cells_len,
                         struct MoraineError *err);

// Dumps every `ducklake_snapshot` row **as this transaction sees it**:
// committed rows at the transaction's read point minus the snapshot
// deletes staged so far. The expiry cascade's own `NOT EXISTS`
// subqueries re-read `ducklake_snapshot` after staging deletes and must
// observe them — a committed-state dump would silently under-reclaim.
// Freed with `moraine_dump_snapshots_free`.
//
// # Safety
//
// `tx` must be a pointer previously returned by [`moraine_tx_begin`]
// and not yet committed or rolled back; its catalog must still be
// attached. `out_items`/`out_len` must be valid, writable pointers.
// `err`, if non-null, must be a valid, writable [`MoraineError`]. All
// for the duration of this call.
int32_t moraine_tx_dump_snapshots(struct MoraineTxHandle *tx,
                                  struct MoraineSnapshotRow **out_items,
                                  size_t *out_len,
                                  struct MoraineError *err);

